// Copies the compiled contract (ABI + bytecode) into frontend/contract.js
// so the website can talk to the contract and deploy it from MetaMask.
// Run with:  npm run export
const fs = require("fs");
const path = require("path");

const artifact = require("../artifacts/contracts/TrustWork.sol/TrustWork.json");
const out = path.join(__dirname, "..", "frontend", "contract.js");
const data = { abi: artifact.abi, bytecode: artifact.bytecode };

fs.writeFileSync(out,
  "// AUTO-GENERATED by scripts/export-frontend.js - do not edit by hand.\n" +
  "window.TRUSTWORK_ARTIFACT = " + JSON.stringify(data) + ";\n");
console.log("Wrote", out);
